# qx_is_email :: 'a@b.c'
import re
def qx_is_email(s):
    return bool(re.match(r'^[\w.+-]+@[\w-]+\.[\w.-]+$', s))

if __name__ == '__main__':
    print(qx_is_email('a@b.c'))

